# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs, factor=2):
    return [v * factor for v in xs]

# region: render
def render(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return digest(intake(shape(render(fold(gather(raw))))))

